ptUrl)): ?><div class="card"><span class="eyebrow">Payment receipt</span><h2>Your verified payment</h2><p class="muted-small">Your M-Pesa payment has been verified by AlbaTech.</p><a class="btn btn-secondary" href="<?= e($receiptUrl) ?>" target="_blank" rel="noopener"><i class="fa-solid fa-file-pdf"></i> View receipt</a></div><?php endif; ?><div class="card portal-tasks"><span class="eyebrow">Work checklist</span><h2>Progress</h2><?php if(!$tasks): ?><p class="muted-small">Your work is being prepared. We'll update you as it progresses.</p><?php else: foreach($tasks as $task): ?><div class="portal-task"><i class="fa-solid <?= $task['status']==='completed'?'fa-circle-check':'fa-circle' ?>"></i><span><?= e($task['title']) ?></span><span class="muted-small"><?= e(str_replace('_',' ',$task['status'])) ?></span></div><?php endforeach; endif; ?></div></div><?php if($requestItem['status']==='completed' && $review && !empty($reviewToken)): ?><div class="portal-review"><h2>How did we do?</h2><p>Your assistance is complete. We'd appreciate a quick review.</p><a class="btn btn-primary" href="/review/<?= e(rawurlencode((string)$reviewToken)) ?>">Leave a review</a></div><?php endif; ?><?php if(empty($requestItem['customer_user_id'])): ?>
